private void GroupHeader1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
System.Resources.ResourceManager  rm = new System.Resources.ResourceManager("Resources.Strings",System.Reflection.Assembly.Load("App_GlobalResources"));
	var parametraRaporti = AlphaWebReports.raporteUtil.DeserializoParametraPerKonstruktorRaporti(this.Extensions["parametraRaporti"]);

            if (GetCurrentColumnValue("lloji") != null)
            {
                if (GetCurrentColumnValue("lloji").ToString() == "FK")
                    xrLabel26.Text = rm.GetString("labelRaportKlienti", parametraRaporti.Ci);
                else
                    xrLabel26.Text = rm.GetString("labelFurnitori", parametraRaporti.Ci);

            }
}

private void xrLabel9_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
if (GetCurrentColumnValue("NIVELREGJISTRIMI") != null)
            {
                string llojDok = GetCurrentColumnValue("NIVELREGJISTRIMI").ToString();
                string nrDok = GetCurrentColumnValue("NRDOKGJENDJEKF").ToString();
                string idDok = GetCurrentColumnValue("IDDOKUMENTI").ToString();
                string url = AlphaWebReports.raporteUtil.ktheUrlDokumentiRaportKlientFurnitor( llojDok, idDok, nrDok, scopeID );
                if (url != "")
                {
                    xrLabel9.NavigateUrl = url;
                    xrLabel9.ForeColor = Color.SteelBlue;
                    xrLabel9.Target = "_self";
                }
            }
}

