private void xrLabel35_SummaryRowChanged(object sender, System.EventArgs e) 
{
	if (GetCurrentColumnValue("lloji") != null)
	{
		if (GetCurrentColumnValue("lloji").ToString() == "FK" 
			|| GetCurrentColumnValue("lloji").ToString() == "FF" )
                  totali += Convert.ToDouble(GetCurrentColumnValue("VleraPaLikujduar"));
		else
			totali -= Convert.ToDouble(GetCurrentColumnValue("VleraPaLikujduar"));
	}
}

