private void xrTableCell31_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
if(GetCurrentColumnValue("DtMaturimi") != null)
{
DateTime dt = DateTime.Parse(GetCurrentColumnValue("DtMaturimi").ToString());
DateTime datenow = DateTime.Now;

TimeSpan t = datenow - dt ;
double NrOfDays = t.TotalDays;


if( NrOfDays  < (int.Parse(Int2)))
xrTableCell31.Text =  String.Format("{0:#,#.00}", Convert.ToDouble(GetCurrentColumnValue("VleraPaLikujduar")));
else
xrTableCell31.Text = "";
}
}


